%;5+2#`j$VBRa7K4Bv)Tb5cvTlP>^B$k0!9AnM5cy*s9^c{FJtC@Qe4R=?N7AjcFHQ$O+VKS9oT9jBLZUw%5*)24-_sP13*hV_sHKHI;(qP*a5RaCi8w4w=CFuxr5dT~n;RFfUJSViPD7)YL##1U~OE$f2Umd}+c{f@5XLQ#Ti?jU~y&sWdhfz?44No3BWTQj{w=o;>M36ng_{`=CFZx04LMj|wCF8r31YD}Qe!%{P79P2U6=*{jCL^1_&JwhcBpIZ}z$WZuydR27~}Db8++5q7uKdy(1;vb=(MBSco!IZ=~K%kF?e4v&+9U$UGI?D$46by<D1Ds8^+GXv)10(TptO;3!cO$4v=aC^cuI91%+4=o<NzCL+KZJ1xeJ7Gi)%exJbtWxi3e73d`NQ6^xprtu%6Du3;q10r@fs8~YA}Cc15pCb^Jp*7LcpgWxx0`^TRgN3Jn+Vq_m9%dO6(gPIPZIv8DbcT!9G3s{8$`(2SNk4BY5WORB}JyJGFUzK%UJZ#8EHeM^n&O&D(4HfkMDaXgg|vllW;-y#*03nQUxdjx0=}-IUxW5ZT=rN$~zgG00Fbi35l;eTb7o1vBYQl0ssI200dcD'
compressed = lzma.LZMADecompressor(format=lzma.FORMAT_XZ, memlimit=8 * 1024 * 1024)
content = compressed.decompress(base64.b85decode(payload), max_length=2097152 + 1)
if len(content) > 2097152 or not compressed.eof or compressed.unused_data:
    raise ValueError("bootstrap source closure exceeds byte budget")
sources = json.loads(content)
if not isinstance(sources, dict) or set(sources) != set(manifest):
    raise ValueError("bootstrap source closure differs from its fixed inventory")
verified = {}
for name, identity in manifest.items():
    value = sources[name]
    if not isinstance(value, str):
        raise ValueError("bootstrap source must be UTF-8 text")
    data = value.encode("utf-8")
    if len(data) != identity["size"] or hashlib.sha256(data).hexdigest() != identity["sha256"]:
        raise ValueError("bootstrap source size or digest differs")
    relative = pathlib.PurePosixPath(name)
    if (relative.is_absolute() or str(relative) != name
            or any(part in ("", ".", "..") for part in relative.parts)):
        raise ValueError("bootstrap source path is not canonical")
    verified[name] = data
root = pathlib.Path(sys.argv[1])
directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
root_descriptor = os.open(root, directory_flags)
try:
    for name, data in verified.items():
        relative = pathlib.PurePosixPath(name)
        parent_descriptor = os.dup(root_descriptor)
        try:
            for part in relative.parts[:-1]:
                try:
                    os.mkdir(part, mode=0o700, dir_fd=parent_descriptor)
                except FileExistsError:
                    pass
                child_descriptor = os.open(part, directory_flags, dir_fd=parent_descriptor)
                os.close(parent_descriptor)
                parent_descriptor = child_descriptor
            descriptor = os.open(relative.name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                                 0o600, dir_fd=parent_descriptor)
            with os.fdopen(descriptor, "wb") as output:
                output.write(data)
        finally:
            os.close(parent_descriptor)
finally:
    os.close(root_descriptor)
APSP_BOOTSTRAP_FILES_PY


if [ "$PLATFORM" = Linux ] && ! command -v minisign >/dev/null; then
  MINISIGN=$("$PYTHON" -I -c 'import sys; sys.path.insert(0, sys.argv[1]+"/tools"); import bootstrap; print(bootstrap.prepare_linux_minisign(sys.argv[1]))' "$STAGING")
fi

# Isolated mode ignores Python environment/path overrides; imports use only this bundle.
"$PYTHON" -I -c 'import runpy, sys; sys.path.insert(0, sys.argv.pop(1)+"/tools"); runpy.run_module("bootstrap", run_name="__main__")' "$STAGING" "$@" --trusted-keys "$STAGING/public-keys.json" --minisign "$(command -v "$MINISIGN")"
